package com.neml.badminton.dto;import com.neml.badminton.entity.ConfigurationStatus;import jakarta.validation.constraints.*;import java.math.BigDecimal;
public class AdministrativeConfigurationDtos{
 public record BrandingDto(int version,ConfigurationStatus status,String displayName,String shortName,String logoReference,String primaryColor,String secondaryColor,String sponsorName,String sponsorLogoReference,String publicDescription,String contactInformation,boolean publicVisibility){}
 public record BrandingRequest(@NotNull Integer expectedVersion,@NotBlank@Size(max=150)String displayName,@NotBlank@Size(max=32)String shortName,@Size(max=500)String logoReference,@Pattern(regexp="^#[0-9A-Fa-f]{6}$")String primaryColor,@Pattern(regexp="^#[0-9A-Fa-f]{6}$")String secondaryColor,@Size(max=150)String sponsorName,@Size(max=500)String sponsorLogoReference,@Size(max=4000)String publicDescription,@Size(max=500)String contactInformation,boolean publicVisibility){}
 public record AuctionConfigDto(int version,ConfigurationStatus status,boolean enabled,String auctionType,BigDecimal teamBudget,BigDecimal minimumBid,BigDecimal bidIncrement,int minimumRosterSize,int maximumRosterSize,boolean retainedPlayersAllowed,int maximumRetainedPlayers,boolean unsoldPlayerReauctionAllowed,String purseCarryForwardPolicy,String auctionOrderPolicy,int timerSeconds,BigDecimal maximumBid,Integer maximumPremiumPurchases,boolean captainPreassignmentRequired){}
 public record AuctionConfigRequest(@NotNull Integer expectedVersion,boolean enabled,@Pattern(regexp="OPEN_ASCENDING",message="Only OPEN_ASCENDING is currently supported")String auctionType,@NotNull@Positive@Digits(integer=12,fraction=2) BigDecimal teamBudget,@NotNull@Positive@Digits(integer=12,fraction=2) BigDecimal minimumBid,@NotNull@Positive@Digits(integer=12,fraction=2) BigDecimal bidIncrement,@Min(1)int minimumRosterSize,@Min(1)int maximumRosterSize,boolean retainedPlayersAllowed,@Min(0)int maximumRetainedPlayers,boolean unsoldPlayerReauctionAllowed,@NotBlank String purseCarryForwardPolicy,@NotBlank String auctionOrderPolicy,@Min(5)@Max(300)int timerSeconds,@Positive@Digits(integer=12,fraction=2)BigDecimal maximumBid,@Min(0)Integer maximumPremiumPurchases,boolean captainPreassignmentRequired){}
}
